$t['Automatic setup creates the webhook for this site URL only, or adds the missing events to it and keeps any other events. It saves the Webhook ID used to verify signatures. It never deletes webhooks, never touches other URLs and never changes the app permissions.'] = 'Az automatikus beállítás csak ehhez a webhely-URL-hez hozza létre a webhookot, vagy hozzáadja a hiányzó eseményeket, és megtartja a többi eseményt. Elmenti az aláírások ellenőrzéséhez használt Webhook ID-t. Soha nem töröl webhookokat, nem módosít más URL-eket, és nem változtatja meg az alkalmazás jogosultságait.';
$t['Automatic setup needs Webhook Endpoints: Write. It creates the webhook and securely saves its new signing secret, or enables the existing endpoint and adds missing events. It preserves existing events and does not replace endpoints or change API key permissions.'] = 'Az automatikus beállításhoz Webhook Endpoints: Write jogosultság szükséges. Létrehozza a webhookot és biztonságosan elmenti az új aláíró titkos kulcsát, vagy engedélyezi a meglévő végpontot és hozzáadja a hiányzó eseményeket. Megőrzi a meglévő eseményeket, nem cseréli le a végpontokat, és nem módosítja az API-kulcs jogosultságait.';
