$t['Final test: complete a sandbox purchase, confirm an HTTP 200 delivery in Stripe, then check the wallet or rental, subscription access and video playback. Also test a declined card and 3D Secure. Never retry a charged payment just because access is still pending.'] = 'Végső teszt: hajts végre egy sandbox vásárlást, ellenőrizd a HTTP 200-as kézbesítést a Stripe-ban, majd ellenőrizd a pénztárcát vagy a kölcsönzést, az előfizetéses hozzáférést és a videólejátszást. Teszteld az elutasított kártyát és a 3D Secure-t is. Soha ne próbálj újra egy már terhelt fizetést csak azért, mert a hozzáférés még függőben van.';
