$t['The <a href=\'{videoLink}\'>{videoName}</a> video was reported as inappropriate from {user} '] = 'A <a href=\'{videoLink}\'>{videónév}</a> videót a {felhasználó} nem megfelelőnek minősítette.';
$t['The account could not be connected. Please try again.'] = 'A fiókot nem sikerült csatlakoztatni. Kérjük, próbálja újra.';
$t['The administrator will verify the payment'] = 'Az adminisztrátor ellenőrizni fogja a fizetést';
$t['The broadcast was interrupted. Please try again.'] = 'A közvetítés megszakadt. Kérjük, próbálja újra.';
$t['The camera or microphone request was interrupted. Please try again.'] = 'A kamera- vagy mikrofonkérés megszakadt. Kérjük, próbálja újra.';
$t['The captcha is empty'] = 'A captcha üres';
$t['The captcha is wrong'] = 'A captcha rossz';
