$t['The check could not finish. Reload the page and try again.'] = 'Az ellenőrzés nem fejeződött be. Töltse újra az oldalt, és próbálja újra.';
$t['The comment is empty'] = 'The comment is empty';
$t['The commit identifies the Git revision checked out on this server; local file edits are not included. A Git tag is shown when one points directly to that commit.'] = 'A commit a szerveren kikért Git-revíziót azonosítja; a helyi fájlmódosítások nem szerepelnek benne. Git-címke akkor jelenik meg, ha közvetlenül erre a commitra mutat.';
$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = 'A Companion Chat szolgáltatás jelenleg nem érhető el. Kérje meg a webhely adminisztrátorát, hogy ellenőrizze az AI bővítmény kapcsolatát.';
$t['The connection could not be renewed. Please reconnect your account.'] = 'A kapcsolatot nem sikerült megújítani. Kérjük, csatlakoztassa újra a fiókját.';
$t['The connection expired and could not be renewed. Please reconnect your account.'] = 'A kapcsolat lejárt, és nem sikerült megújítani. Kérjük, csatlakoztassa újra a fiókját.';
$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'A célponttal való kapcsolat a stream közben megszakadt. Ez átmeneti hálózati probléma lehet; az FFMPEG megpróbál újracsatlakozni.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'A YouTube-bal való kapcsolat megszakadt. A feltöltés szünetel, és folytatható.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = 'A kapcsolat megszakadt. Ellenőrizd a fiókodat, mielőtt újra megpróbálod ezt az előfizetést.';
$t['The connection was renewed.'] = 'A kapcsolat megújult.';
$t['The connection window was closed before the authorization finished. No account was connected.'] = 'A csatlakozási ablak bezárult, mielőtt az engedélyezés befejeződött. Nem lett fiók csatlakoztatva.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'A konvertált fájlok megmaradtak. Az átvitel újrapróbálásához lépj kapcsolatba az oldal adminisztrátorával; a videót nem kell újra feltöltened.';
$t['The converted video could not be sent back to this site.'] = 'A konvertált videót nem sikerült visszaküldeni erre az oldalra.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'A kiválasztott kártya ügyfelei. Keress, rendezz, másold ki az e-mail-címeket, vagy exportálj mindent táblázatba.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'Az oldal napi YouTube-feltöltési kvótája elfogyott. A feltöltések csendes-óceáni idő szerint éjfél után válnak újra elérhetővé. Kérjük, próbáld újra később.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'Az adatbázis verziója csak adatbázis-migráció alkalmazásakor változik. Nem várható, hogy egyezzen a kiadási címkével vagy a commit-tal.';
$t['The default'] = 'Az alapértelmezett';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'A cél RTMP-szerver elutasította a kapcsolatot. Ellenőrizd a stream URL-t, és győződj meg róla, hogy a szerver elérhető.';
$t['The destination server requires authentication. Check the stream key.'] = 'A célszerver hitelesítést igényel. Ellenőrizd a streamkulcsot.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'A célszerver 403-as hibát adott vissza. Lehet, hogy a streamkulcs érvénytelen vagy lejárt.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'A célvideót eltávolították, vagy ez a fiók nem szerkesztheti. Ellenőrizd a videót és a fiók hozzáférését az oldalon.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'A letöltést a rendszer ellenőrzi, a felhasználónak nincs mit ellenőrizni.';
$t['The download permission is site wide, so there is nothing to check on the video'] = 'A letöltési engedély az egész oldalra vonatkozik, így a videón nincs mit ellenőrizni';
$t['The download permission is site wide, so there is nothing to check onthe video'] = 'A letöltési engedély az egész oldalra érvényes, így nincs mit ellenőrizni a videón.';
$t['The email is invalid'] = 'Az e-mail érvénytelen';
$t['The encoder could not download the original file.'] = 'Az encoder nem tudta letölteni az eredeti fájlt.';
$t['The encoder could not find this video on the site.'] = 'Az encoder nem találta ezt a videót az oldalon.';
$t['The encoder did not confirm that the video was added to the queue. Please retry.'] = 'Az encoder nem erősítette meg, hogy a videó bekerült a sorba. Kérjük, próbáld újra.';
$t['The encoder is running out of disk space'] = 'Az encoder lemezterülete fogyóban van';
$t['The encoder reported an unexpected error.'] = 'Az encoder váratlan hibát jelzett.';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = 'A kódolási folyamat váratlanul leállt, és az automatikus újrapróbálkozások is sikertelenek voltak.';
$t['The encoding queue is stalled'] = 'A kódolási sor elakadt';
$t['The event purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'Az esemény megvásárlását nem sikerült befejezni. A tárcás fizetés nem lett levonva. Ellenőrizd az egyenlegedet, mielőtt újra próbálkozol.';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = 'A fájlt nem sikerült konvertálni. Lehet, hogy sérült, vagy olyan formátumú, amelyet az encoder nem támogat.';
$t['The file must be an .vtt file!'] = 'A fájlnak .vtt fájlnak kell lennie!';
$t['The file must be an .vtt or .srt file!'] = 'A fájlnak .vtt vagy .srt fájlnak kell lennie!';
$t['The final charge uses the duration measured during processing. A connected Marketplace wallet is required.'] = 'A végső terhelés a feldolgozás során mért időtartamon alapul. Csatlakoztatott Marketplace-tárca szükséges.';
$t['The following movie contains materials that are not suitable for children 17 and under.'] = 'A következő film 17 éves és fiatalabb gyermekek számára nem megfelelő tartalmat tartalmaz.';
$t['The following movie contains materials that may not be suitable for children 17 and under.'] = 'A következő film 17 éves és fiatalabb gyermekek számára esetleg nem megfelelő tartalmat tartalmaz.';
$t['The form to signup will not exists'] = 'A regisztrációs űrlap nem létezik';
$t['The gift code has been canceled. If this is unexpected, please contact our support team.'] = 'Az ajándékkódot visszavonták. Ha ez váratlan, kérjük, lépj kapcsolatba ügyfélszolgálatunkkal.';
$t['The gift code is currently inactive. Please check back later or contact support.'] = 'Az ajándékkód jelenleg inaktív. Kérjük, nézz vissza később, vagy lépj kapcsolatba az ügyfélszolgálattal.';
$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = 'A fenti adatok megfelelnek hivatalos nyilvántartásunknak, és igazolják a tanúsítvány hitelességét.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'A bemeneti stream érvénytelen adatokat tartalmaz. Lehet, hogy a forrás HLS még nem áll készen, vagy a stream megszakadt.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'A telepített PHP-csomag mindkét javítást tartalmazza, de ez a webes folyamat még a frissítés előtt betöltött példányt futtatja. Indítsd újra az Apache-t vagy a PHP-FPM-et.';
$t['Their last plans add up to %s'] = 'Utolsó csomagjaik összege %s';
$t['The list was limited to the first %s results.'] = 'A lista az első %s találatra korlátozódott.';
$t['The live service could not complete the request. Please try again.'] = 'Az élő szolgáltatás nem tudta teljesíteni a kérést. Kérjük, próbáld újra.';
$t['The live that was still being sent to this destination was stopped.'] = 'Az erre a célhelyre még küldött élő adás leállt.';
$t['Theme for Style:'] = 'Téma a stílushoz:';
$t['Themes'] = 'Témák';
$t['The number of lines in both columns must be the same'] = 'A két oszlop sorainak számának meg kell egyeznie';
$t['The original file for this video does not exists anymore'] = 'Az eredeti fájl ehhez a videóhoz már nem létezik';
$t['The Permissions Plugin is not installed. Please install it if you want to customize the permissions.'] = 'A Permissions Plugin nincs telepítve. Kérjük, telepítse, ha testre szeretné szabni az engedélyeket.';
$t['The plugin is disabled'] = 'A plugin le van tiltva';
$t['The program is empty'] = 'A program üres';
$t['The purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'A vásárlást nem sikerült befejezni. A tárcás fizetés nem lett levonva. Ellenőrizd az egyenlegedet, mielőtt újra próbálkozol.';
$t['There\'s an unknown status associated with this gift code. Please contact support for assistance.'] = 'Ehhez az ajándékkódhoz ismeretlen állapot tartozik. Segítségért kérjük, lépj kapcsolatba az ügyfélszolgálattal.';
$t['There, you can set'] = 'Ott beállíthatja';
$t['There are no notifications'] = 'Nincsenek értesítések';
$t['There are no upcoming events for this channel'] = 'Ennek a csatornának nincsenek közelgő eseményei';
$t['There are various kinds of media you can integrate here. They are working different'] = 'Különböző típusú médiumok integrálhatók ide. Ezek különbözőképpen működnek';
$t['The recover pass does not match!'] = 'A visszaszerzési passz nem egyezik!';
$t['The regular form to signin will not exist, if you check this will only have social login or LDAP option'] = 'A rendszeres bejelentkezési űrlap nem fog létezni, ha ezt bejelölöd, akkor csak havesocial login vagy LDAP opciót fogsz kapni.';
$t['There is missing data to recover your password'] = 'Hiányoznak adatok a jelszó visszaállításához';
$t['There is no Pay Per View plan yet. Create one in the Pay-Per-View plugin, PPV Plans tab.'] = 'Még nincs Pay Per View csomag. Hozz létre egyet a Pay-Per-View bővítmény PPV Plans lapján.';
$t['There is no plan that can hold videos yet. Create one in the PPV Plans tab, then come back here.'] = 'Még nincs videókat tartalmazni képes csomag. Hozz létre egyet a PPV Plans lapon, majd térj vissza ide.';
$t['There is no streaming now'] = 'Most nincs streaming';
$t['The release number and the AVideo database version are independent. Code update status is determined by commit history.'] = 'A kiadás száma és az AVideo adatbázis-verziója független egymástól. A kód frissítési állapotát a commit-előzmények határozzák meg.';
$t['The request to the social network failed. Please try again later.'] = 'A közösségi hálózathoz intézett kérés sikertelen volt. Kérjük, próbáld újra később.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'A restreamer szerver nem éri el a célhelyet. Ellenőrizd a hálózati kapcsolatot.';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'Amíg a probléma fennáll, ugyanaz a riasztás legfeljebb %s gyakorisággal ismétlődik.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'Amíg a probléma fennáll, ugyanaz a riasztás legfeljebb néhány óránként ismétlődik.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'A kiválasztott kamera vagy mikrofon nem érhető el. Kérjük, válassz másik eszközt.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'A kiválasztott pozíció egy valódi oldalon van kiemelve. A mobil előnézet csak a hirdetések pozícióit módosítja; az oldal többi része a böngésződ eszközét használja.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'A kiválasztott pozíció körvonallal jelölve látható a webhely egy valódi oldalán, és követi az alább kiválasztott pozíciót. A mobil előnézet csak a hirdetések pozícióit módosítja; az oldal többi része a böngészője eszközét használja.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'Az oldal egy adatbázis-probléma miatt jelenleg nem érhető el. Dolgozunk a probléma mielőbbi megoldásán.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'Az oldal átmenetileg nem érhető el, mert a szerver lemeze megtelt. Dolgozunk a problémán, hamarosan visszatérünk.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'Az oldal karbantartás alatt áll, mert a szerver lemeze majdnem megtelt. Foglalkozunk a problémával, hamarosan visszatérünk.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'Az oldal megtagadta a hozzáférést. Újítsd meg az encoder-fiók hozzáférését, és ellenőrizd a feltöltési jogosultságait.';
$t['The site will display only a login form to un authenticated users'] = 'Az oldal csak egy bejelentkezési űrlapot jelenít meg a nem hitelesített felhasználók számára.';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = 'A forrásstream véget ért. Ha az élő adást szándékosan állították le, ez normális.';
$t['The split is on: desktop visitors do not see this banner now, they see the left and right halves.'] = 'A felosztás be van kapcsolva: az asztali látogatók most nem ezt a bannert látják, hanem a bal és jobb felét.';
$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'A streamben időbélyeg-folytonossági hiányok vannak. Ez pufferelést vagy lejátszási problémákat okozhat a célplatformon.';
$t['The subtitle has not been copied to the player yet.'] = 'A feliratot még nem másolták át a lejátszóba.';
$t['The subtitle is already on the player.'] = 'A felirat már a lejátszóban van.';
$t['The subtitle was copied to the player.'] = 'A felirat át lett másolva a lejátszóba.';
$t['The subtitle will be available when processing finishes.'] = 'A felirat a feldolgozás befejezése után lesz elérhető.';
$t['The upload could not be started. Please try again.'] = 'A feltöltést nem sikerült elindítani. Kérjük, próbáld újra.';
$t['The upload did not start. Click Resume to try again.'] = 'A feltöltés nem indult el. Kattints a Folytatás gombra az újrapróbáláshoz.';
