$t['YouTube returned an unexpected error. Please try again later. If the problem continues, contact the site administrator.'] = 'A YouTube váratlan hibát adott vissza. Próbáld újra később. Ha a probléma továbbra is fennáll, vedd fel a kapcsolatot a webhely adminisztrátorával.';
$t['YouTube URL'] = 'YouTube URL';
